<?php require_once 'config/db.php';require_once 'includes/auth.php';require_role(['admin']);$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$email=trim($_POST['email']);$role=$_POST['role'];$pw=$_POST['password'];$allowed=['admin','sales','warehouse','shipping_staff','report_staff','confirmation_staff'];if(!in_array($role,$allowed,true))$err='Invalid staff role.';elseif(strlen($pw)<8)$err='Password must be at least 8 characters.';else{$hash=password_hash($pw,PASSWORD_DEFAULT);$address='Staff';$s=$conn->prepare('INSERT INTO users(name,email,password,role,address) VALUES(?,?,?,?,?)');$s->bind_param('sssss',$name,$email,$hash,$role,$address);if($s->execute()){header('Location:users.php?msg=Staff+account+created');exit;}else $err='Email already exists.';}}$rows=$conn->query("SELECT id,name,email,role,created_at FROM users WHERE role<>'customer' ORDER BY id");include 'includes/header.php';?><div class="card"><h2>Staff Accounts & Permissions</h2><p>Create staff logins with access limited by role.</p><?php if($err):?><div class="error"><?=h($err)?></div><?php endif;?><form method="post" class="grid"><div><label>Name</label><input name="name" required></div><div><label>Email</label><input type="email" name="email" required></div><div><label>Temporary password (8+ chars)</label><input type="password" name="password" minlength="8" required></div><div><label>Role / Access</label><select name="role"><option value="shipping_staff">Shipping only</option><option value="report_staff">Reports only</option><option value="confirmation_staff">Order confirmation only</option><option value="warehouse">Warehouse (shipping)</option><option value="sales">Sales (confirmation and customers)</option><option value="admin">Administrator (all access)</option></select></div><div><button class="btn success">Create Staff Account</button></div></form></div><div class="card"><h3>Existing Staff</h3><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Created</th></tr><?php while($x=$rows->fetch_assoc()):?><tr><td><?=h($x['name'])?></td><td><?=h($x['email'])?></td><td><?=h($x['role'])?></td><td><?=h($x['created_at'])?></td></tr><?php endwhile;?></table><p><b>Permissions:</b> shipping_staff can ship/mark delivered; report_staff can only view reports; confirmation_staff can accept/reject orders and mark processing.</p></div><?php include 'includes/footer.php';?>